clean_output:
so as to prevent
          them to be processed later (just as in os.walk())

        --it can return a list of tuples (dirPath, dirNames, fileNames),
          which will be processed as if they were the result of os.walk(dirPath).

        The parameter "currentDirFilter" is called with the current directory
        as its only parameter.
        """
        if not os.path.isdir(rootPath):
            raise ValueError('rootPath must be a directory')
        if currentDirFilter is not None and not callable(currentDirFilter):
            raise ValueError('currentDirFilter must be a callable function')
        result = []
        for dirPath, dirNames, fileNames in os.walk(rootPath):
            if currentDirFilter is not None:
                currentDirFilter(dirPath, dirNames, fileNames)
            for fileName in fileNames:
                result.append(LinearWalkItem(os.path.join(dirPath, fileName)))
            for dirName in dirNames:
                result.append(LinearWalkItem(os.path.join(dirPath, dirName)))
        return result
